@dataclass(frozen=True)
class Req:
    code: str | None
    text: str  # the requirement as printed; "<br/>" marks a forced line end, "|" a page break inside it
    parents: tuple[str, ...] = ()
    note: str | None = None  # a Note inside the requirement column, before the trace
    full_note: str | None = None  # a full-width Note after the trace
    items: tuple[str, ...] = ()  # list items printed under the requirement text
    marker: str = "\u2013"  # a dash bullet ("•" in the standard PDF fonts extracts as "(cid:127)"), or "" for lettered items
    items_break_after: int | None = None  # a page break inside the list, after this many items
    parents_break_after: int | None = (
        None  # a page break inside the trace, after this many parent codes
    )

    @property
    def plain(self) -> str:
        return " ".join(
            self.text.replace("<br/>", "")
            .replace("|", " ")
            .replace("<i>", "")
            .replace("</i>", "")
            .split()
        )


@dataclass(frozen=True)
class Section:
    number: str
    title: str
    kind: str  # "context" | "front" | "feature" | "empty" | "back"
    reqs: tuple[Req, ...] = ()
    prose: tuple[
        str, ...
    ] = ()  # descriptive sentences (context), or the one-line body of an empty section
    break_before: bool = False


def _spread(first: int, last: int, n: int) -> list[int]:
    return [round(first + i * (last - first) / (n - 1)) for i in range(n)] if n > 1 else [first]


# TV twin content: a fictional television set (receiver + remote control), written like a requirements-tool export. Inserted into the
# twin builder's layout. Every name, value and sentence is invented.

_P = ["TVS_{n}", "SYS_{n}", "MRD_{n}", "SYS_{n}.{m}"]


def _tr(seed: int) -> tuple[str, ...]:
    """Parent codes for the trace under a requirement (1 or 2 codes), deterministic."""
    a = _P[seed % 4].format(n=seed % 40 + 2, m=seed % 3 + 1)
    b = _P[(seed + 1) % 4].format(n=seed % 60 + 10, m=seed % 4 + 1)
    return (a,) if seed % 3 == 0 else (a, b)


def R(code, text, seed, **kw):  # noqa: N802
    return Req(code, text, kw.pop("parents", _tr(seed)), **kw)


