def _stamp(c) -> None:  # noqa: ANN001
    """A confidentiality stamp at the top right of the cover, tilted like a rubber stamp, next to the document title."""
    from reportlab.lib import colors

    red = colors.Color(0.78, 0.1, 0.12)
    c.saveState()
    c.translate(438, 505)
    c.rotate(14)
    c.setStrokeColor(red)
    c.setFillColor(red)
    c.setLineWidth(2.2)
    c.roundRect(-8, -30, 150, 62, 6, stroke=1, fill=0)
    c.setLineWidth(0.8)
    c.roundRect(-4, -26, 142, 54, 4, stroke=1, fill=0)
    c.setFont("Helvetica-Bold", 15)
    c.drawCentredString(67, 8, "CONFIDENTIAL")
    c.setFont("Helvetica-Bold", 8)
    c.drawCentredString(67, -6, "HALVAR ELECTRONICS LTD")
    c.setFont("Helvetica", 7)
    c.drawCentredString(67, -18, "Ref. 220.3 · Do not copy")
    c.restoreState()


ABBREVIATIONS = [
    (f"A{chr(65 + i // 26)}{chr(65 + i % 26)}", f"invented abbreviation number {i + 1}")
    for i in range(35)
]
DEFINITIONS = (
    "A picture mode is a named set of picture settings.",
    "Standby is the state in which the set waits for a command with the panel off.",
)
REFERENCES = [
    ("[1]", "HV-STD-0012", "Product safety rules"),
    ("[2]", "HV-STD-0031", "Remote control key layout"),
]


@dataclass
class TwinTruth:
    epic_title_contains: str
    sections: tuple[Section, ...]
    requirements: list[tuple[str, Req]] = field(
        default_factory=list
    )  # (section number, requirement)
    furniture: list[str] = field(
        default_factory=list
    )  # running header values and margin notice lines: never inside an item
    front_matter: list[str] = field(default_factory=list)  # never an item, never inside one
    back_matter_codes: list[str] = field(default_factory=list)
    not_customer_ids: list[str] = field(
        default_factory=list
    )  # uppercase tokens inside requirement text


def twin_truth() -> TwinTruth:
    truth = TwinTruth(epic_title_contains=SYSTEM_NAME, sections=SECTIONS)
    for s in SECTIONS:
        truth.requirements += [(s.number, r) for r in s.reqs]
    truth.furniture = [*HEADER_VALUES, *MARGIN_NOTICE]
    truth.front_matter = [
        COVER_NOTICE[:60],
        GENERATION_STAMP[0],
        *[a[1] for a in ABBREVIATIONS[:5]],
        *[r[2] for r in REFERENCES],
        *DEFINITIONS,
    ]
    truth.back_matter_codes = [f"vts_{r.code}" for _, r in truth.requirements if r.code]
    truth.not_customer_ids = [
        "KLX4410",
        "QV20417",
        "TRMSA-310",
        "HMI_PANEL",
        "CT_FUNCTION",
        "SW_DESIGN",
        "GCS_",
        "SYS_",
        "CLIMAT_",
    ]
    return truth


def build_twin_spec_pdf(out_dir: Path) -> tuple[Path, TwinTruth]:
    from reportlab.lib import colors
    from reportlab.lib.pagesizes import LETTER
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.platypus import (
        Flowable,
        KeepTogether,
        PageBreak,
        Paragraph,
        SimpleDocTemplate,
        Spacer,
        Table,
        TableStyle,
    )

    width, height = LETTER
    body = ParagraphStyle(
        "Body", fontName="Helvetica", fontSize=11, leading=14, spaceBefore=3, spaceAfter=3
    )
    small = ParagraphStyle("Small", parent=body, fontSize=8, leading=10)
    title_style = ParagraphStyle(
        "CoverTitle",
        parent=body,
        fontName="Helvetica-Bold",
        fontSize=16,
        leading=20,
        spaceBefore=24,
    )
    system_style = ParagraphStyle(
        "CoverSystem", parent=body, fontName="Helvetica-Bold", fontSize=15, leading=19
    )
    center = ParagraphStyle("Center", parent=body, alignment=1)
    contents_heading = ParagraphStyle(
        "ContentsHeading",
        parent=body,
        fontName="Helvetica-Bold",
        fontSize=14,
        leading=18,
        spaceAfter=8,
    )
    contents_entry = ParagraphStyle(
        "ContentsEntry", parent=body, spaceBefore=0, spaceAfter=0, leading=13
    )
    heading = {
        1: ParagraphStyle("H1", parent=body, fontName="Helvetica-Bold", spaceBefore=12),
        2: ParagraphStyle("H2", parent=body, spaceBefore=10),
        3: ParagraphStyle("H3", parent=body, spaceBefore=8),
        4: ParagraphStyle("H4", parent=body, spaceBefore=8),
    }
    req_style = ParagraphStyle(
        "Req",
        parent=body,
        leftIndent=70,
        bulletIndent=0,
        bulletFontName="Helvetica",
        bulletFontSize=11,
        spaceBefore=8,
    )
    req_more = ParagraphStyle("ReqMore", parent=body, leftIndent=70, spaceBefore=0)
    trace = ParagraphStyle(
        "Trace", parent=body, leftIndent=70, spaceBefore=1, spaceAfter=0, leading=13
    )
    item_style = ParagraphStyle(
        "Item", parent=body, leftIndent=92, bulletIndent=76, spaceBefore=0, spaceAfter=0
    )
    grid = TableStyle(
        [("GRID", (0, 0), (-1, -1), 0.5, colors.black), ("FONTSIZE", (0, 0), (-1, -1), 9)]
    )

    class Bookmark(Flowable):
        """Adds an outline entry for the heading that follows (the export tool writes one per heading)."""

        def __init__(self, title: str, level: int, key: str) -> None:
            super().__init__()
            self.title, self.level, self.key = title, level, key
            self.width = self.height = 0

        def draw(self) -> None:
            self.canv.bookmarkPage(self.key)
            self.canv.addOutlineEntry(self.title, self.key, self.level - 1, closed=False)

    flow: list = [
        Spacer(1, 20),
        Paragraph("COMPANY CONFIDENTIAL", body),
        Paragraph(COVER_NOTICE, small),
        Paragraph(COMPANY, small),
        Paragraph(DOC_TYPE, title_style),
        Paragraph("[220.3] Vireo Television<br/>Set (VTS)", system_style),
        Paragraph("for", center),
        Paragraph("LARK PROGRAMME", center),
        Spacer(1, 40),
        Paragraph("Prepared by", body),
        Paragraph(COMPANY, body),
        Spacer(1, 120),
        Paragraph(GENERATION_STAMP[0], small),
        Paragraph(GENERATION_STAMP[1], small),
        PageBreak(),
        Paragraph("CONTENTS", contents_heading),
    ]
    page_guess = 3
    for s in SECTIONS:
        level = s.number.count(".") + 1
        if level > 3:
            continue
        page_guess += 1 if s.reqs else 0
        indent = "&nbsp;" * 4 * (level - 1)
        label = f"{s.number} {s.title}"
        dots = "." * max(4, 70 - len(label) - 4 * (level - 1))
        flow.append(Paragraph(f"{indent}{label} {dots} {page_guess}", contents_entry))
    flow.append(PageBreak())

    def add_heading(s: Section) -> None:
        level = s.number.count(".") + 1
        text = f"{s.number} {s.title}"
        flow.append(
            KeepTogether([Bookmark(text, level, f"h{s.number}"), Paragraph(text, heading[level])])
        )  # the outline entry points at the heading's own page

    def add_requirement(r: Req) -> None:
        first, _, rest = r.text.partition("|")
        flow.append(
            Paragraph(first, req_style, bulletText=r.code)
            if r.code
            else Paragraph(first, ParagraphStyle("ReqNoCode", parent=req_style))
        )
        if rest:
            flow.extend([PageBreak(), Paragraph(rest, req_more)])
        for i, item in enumerate(r.items):
            if r.items_break_after is not None and i == r.items_break_after:
                flow.append(PageBreak())
            if r.marker:
                flow.append(Paragraph(item, item_style, bulletText=r.marker))
            else:
                letter, _, text = item.partition(" ")
                flow.append(Paragraph(text, item_style, bulletText=letter))
        if r.note:
            flow.append(Paragraph(r.note, req_more))
        if r.parents:
            flow.append(Paragraph(TRACE_LABEL, trace))
            for i, parent in enumerate(r.parents):
                if r.parents_break_after is not None and i == r.parents_break_after:
                    flow.append(PageBreak())
                flow.append(Paragraph(parent, trace))
        if r.full_note:
            flow.append(Paragraph(r.full_note, body))

    truth = twin_truth()
    for s in SECTIONS:
        if s.break_before:
            flow.append(PageBreak())
        add_heading(s)
        for sentence in s.prose:
            flow.append(Paragraph(sentence, body))
        if s.number == "1.3":
            flow.append(
                Table(
                    [["Issue", "Date", "Change", "Approved"]],
                    style=grid,
                    colWidths=[60, 80, 200, 100],
                )
            )
        elif s.number == "1.4":
            flow.append(Table([list(r) for r in REFERENCES], style=grid, colWidths=[40, 120, 280]))
        elif s.number == "1.5":
            flow.append(Table([list(a) for a in ABBREVIATIONS], style=grid, colWidths=[80, 360]))
            flow += [Paragraph(d, body) for d in DEFINITIONS]
            flow.append(PageBreak())
        elif s.number == "3":
            rows = [["Identity in external document", "Identity in this document"]] + [
                ["", code] for code in truth.back_matter_codes
            ]
            flow.append(Table(rows, style=grid, colWidths=[220, 220], repeatRows=0))
        for r in s.reqs:
            add_requirement(r)

    def furniture(canvas, doc) -> None:
        canvas.saveState()
        top = height - 18
        left, right = 76, width - 75
        canvas.setLineWidth(0.5)
        # Row 1: logo, document type, page number.
        canvas.drawImage(LOGO, left, top - 26, width=62, height=24, mask="auto")
        if doc.page == 1:
            _stamp(canvas)
        canvas.setFont("Helvetica-Bold", 10)
        canvas.drawCentredString(width / 2, top - 16, DOC_TYPE)
        canvas.setFont("Helvetica", 10)
        canvas.drawRightString(right, top - 16, f"{doc.page}({doc._pages_total})")
        # Rows 2-4: a label row over a value row, three times; the lower rows reach below the nominal top margin.
        rows = [
            (("Date", DATE), ("Issue", ISSUE), ("Document ID", DOC_ID)),
            (
                ("Issued by", "Consumer Display Line"),
                ("Classification Company Confidentiality", "FICTIONAL - FOR TESTING ONLY"),
            ),
            (
                ("Classification Export Control", "NOT EXPORT CONTROLLED"),
                ("Classification Defence Secrecy", "NOT CLASSIFIED"),
            ),
        ]
        y = top - 30
        for row in rows:
            x = left
            step = (right - left) / len(row)
            for label, value in row:
                canvas.setFont("Helvetica", 6)
                canvas.drawString(x + 2, y, label)
                canvas.setFont("Helvetica", 8)
                canvas.drawString(x + 2, y - 10, value)
                x += step
            y -= 28
        canvas.line(left, y + 6, right, y + 6)
        # The notice in the left margin, rotated 90 degrees (reads bottom to top).
        canvas.setFont("Helvetica", 7)
        canvas.translate(30, 260)
        canvas.rotate(90)
        for i, line in enumerate(MARGIN_NOTICE):
            canvas.drawString(0, -9 * i, line)
        canvas.restoreState()

    path = Path(out_dir) / "tv_twin_spec.pdf"

    def build(total: int) -> int:
        doc = SimpleDocTemplate(
            str(path),
            pagesize=LETTER,
            topMargin=125,
            bottomMargin=72,
            leftMargin=76,
            rightMargin=75,
            title=DOC_TYPE,
        )
        doc._pages_total = total
        doc.build(copy.deepcopy(flow), onFirstPage=furniture, onLaterPages=furniture)
        return doc.page

    build(build(0))  # two passes, so every page prints "n(total)"
    return path, truth


if __name__ == "__main__":
    import sys

    target = Path(sys.argv[1]) if len(sys.argv) > 1 else Path(__file__).parent
    print(build_twin_spec_pdf(target)[0])
